using uOrgHub.Sms.Models.Enums;

namespace uOrgHub.Sms.DTOs;

public class SendSmsDto
{
    /// <summary>One or more numbers. Each entry may itself hold a comma/semicolon/newline separated list.</summary>
    public List<string> Recipients { get; set; } = new();
    public string Message { get; set; } = string.Empty;
    /// <summary>
    /// Generated by the client once per compose (not per click). Re-sending the same key returns
    /// the original send instead of sending again.
    /// </summary>
    public string IdempotencyKey { get; set; } = string.Empty;
}

public class SendSmsResultDto
{
    public Guid RequestId { get; set; }
    /// <summary>True when this key had already been used and the earlier send is returned.</summary>
    public bool Duplicate { get; set; }
    public string GatewayName { get; set; } = string.Empty;
    public int RecipientCount { get; set; }
    public int SegmentsPerRecipient { get; set; }
    public int TotalSegments { get; set; }
    public SmsEncoding Encoding { get; set; }
    public decimal? EstimatedCost { get; set; }
    public string Currency { get; set; } = "BDT";
}

/// <summary>Progress of one send, polled by the compose page after submitting.</summary>
public class SmsSendRequestStatusDto
{
    public Guid RequestId { get; set; }
    public int RecipientCount { get; set; }
    public int Queued { get; set; }
    public int Submitted { get; set; }
    public int Delivered { get; set; }
    public int Failed { get; set; }
    public int Undetermined { get; set; }
    public bool Completed { get; set; }
    public decimal? Cost { get; set; }
    /// <summary>First few failures, for the result message.</summary>
    public List<SmsFailureDto> Failures { get; set; } = new();
}

public record SmsFailureDto(string Recipient, string? ErrorMessage);

/// <summary>What the compose page shows and checks before sending.</summary>
public class SmsComposeInfoDto
{
    public bool HasActiveGateway { get; set; }
    public Guid? GatewayId { get; set; }
    public string? GatewayName { get; set; }
    public string? ProviderName { get; set; }
    public decimal? RatePerSegment { get; set; }
    public string Currency { get; set; } = "BDT";
    public bool CanSendBulk { get; set; }
    public int MaxRecipients { get; set; }
}

public class SmsMessageListItemDto
{
    public Guid Id { get; set; }
    public string Recipient { get; set; } = string.Empty;
    public string MessagePreview { get; set; } = string.Empty;
    public string GatewayName { get; set; } = string.Empty;
    public string ProviderKey { get; set; } = string.Empty;
    public int Segments { get; set; }
    public SmsEncoding Encoding { get; set; }
    public SmsMessageStatus Status { get; set; }
    public decimal? Cost { get; set; }
    public bool CostIsActual { get; set; }
    public string? ProviderMessageId { get; set; }
    public string? ErrorMessage { get; set; }
    public DateTime CreatedAt { get; set; }
    public DateTime? SubmittedAt { get; set; }
    public string CreatedBy { get; set; } = string.Empty;
}

public class SmsMessageDetailDto : SmsMessageListItemDto
{
    public string MessageText { get; set; } = string.Empty;
    public Guid GatewayId { get; set; }
    public Guid? SendRequestId { get; set; }
    public string? ProviderStatus { get; set; }
    public string? ErrorCode { get; set; }
    public string? ProviderResponse { get; set; }
    public int Attempts { get; set; }
    public DateTime? DeliveredAt { get; set; }
    public DateTime? FailedAt { get; set; }
    public DateTime? LastStatusCheckAt { get; set; }
    public string? Source { get; set; }
    public string? SourceReference { get; set; }
}
